{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2118-07-18 17:30:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I understand you came in because your dialysis access wasn’t working today?"
    },
    {
      "turn_number": 2,
      "time": "2118-07-18 17:31:00",
      "speaker": "Patient",
      "text": "Yes, that’s right. The nurses at dialysis tried to use my arm graft, but couldn’t get it to work. I’ve had this before."
    },
    {
      "turn_number": 3,
      "time": "2118-07-18 17:32:00",
      "speaker": "Doctor",
      "text": "Yes, I see you were here about a month ago for the same issue. We’ll need to check your graft again. How are you feeling otherwise?"
    },
    {
      "turn_number": 4,
      "time": "2118-07-18 17:33:00",
      "speaker": "Patient",
      "text": "I feel okay. No chest pain, no shortness of breath. Just worried I can’t get dialysis."
    },
    {
      "turn_number": 5,
      "time": "2118-07-18 17:34:00",
      "speaker": "Doctor",
      "text": "That’s understandable. We’ll make sure you get dialysis while you’re here. First, we’ll do some blood work and get you set up for a procedure tomorrow to look at your graft."
    },
    {
      "turn_number": 6,
      "time": "2118-07-18 17:35:00",
      "speaker": "Patient",
      "text": "Will they try to fix it again?"
    },
    {
      "turn_number": 7,
      "time": "2118-07-18 17:36:00",
      "speaker": "Doctor",
      "text": "Yes, the transplant surgery team will do a fistulogram and try to clear the clot. But sometimes, if it’s blocked too much, we may need a temporary catheter."
    },
    {
      "turn_number": 8,
      "time": "2118-07-18 17:37:00",
      "speaker": "Patient",
      "text": "I had a catheter once before. I didn’t like it in my neck."
    },
    {
      "turn_number": 9,
      "time": "2118-07-18 17:38:00",
      "speaker": "Doctor",
      "text": "We only use it temporarily. It helps us keep your dialysis on schedule while your arm graft heals or gets repaired."
    },
    {
      "turn_number": 10,
      "time": "2118-07-18 17:39:00",
      "speaker": "Patient",
      "text": "Okay, as long as it’s not forever."
    },
    {
      "turn_number": 11,
      "time": "2118-07-19 09:45:00",
      "speaker": "Doctor",
      "text": "Good morning. You just came back from the procedure. The team tried to open up your graft, but there was a tough blockage they couldn’t fully clear."
    },
    {
      "turn_number": 12,
      "time": "2118-07-19 09:46:00",
      "speaker": "Patient",
      "text": "So it didn’t work?"
    },
    {
      "turn_number": 13,
      "time": "2118-07-19 09:47:00",
      "speaker": "Doctor",
      "text": "Not completely. They opened part of it, but there’s still a narrow spot that didn’t respond to the balloon. Because of that, they decided to place a temporary catheter in your neck for dialysis."
    },
    {
      "turn_number": 14,
      "time": "2118-07-19 09:48:00",
      "speaker": "Patient",
      "text": "Is that safe?"
    },
    {
      "turn_number": 15,
      "time": "2118-07-19 09:49:00",
      "speaker": "Doctor",
      "text": "Yes, it’s very common. We’ll make sure it’s clean and monitored. You’ll get dialysis through it today."
    },
    {
      "turn_number": 16,
      "time": "2118-07-19 09:50:00",
      "speaker": "Patient",
      "text": "And my arm? Will they try again?"
    },
    {
      "turn_number": 17,
      "time": "2118-07-19 09:51:00",
      "speaker": "Doctor",
      "text": "The surgeons recommend an outpatient procedure to repair the graft. They’ll contact you to schedule it."
    },
    {
      "turn_number": 18,
      "time": "2118-07-19 09:52:00",
      "speaker": "Patient",
      "text": "Okay, that’s good to know."
    },
    {
      "turn_number": 19,
      "time": "2118-07-19 14:00:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. Your kidney numbers are improving after dialysis. We’ll keep an eye on your blood counts."
    },
    {
      "turn_number": 20,
      "time": "2118-07-19 14:01:00",
      "speaker": "Patient",
      "text": "I’ve been anemic before. Is that still a problem?"
    },
    {
      "turn_number": 21,
      "time": "2118-07-19 14:02:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin is lower than ideal, but it’s expected with kidney disease. You’re on erythropoietin, which helps. We’ll keep monitoring it."
    },
    {
      "turn_number": 22,
      "time": "2118-07-20 10:00:00",
      "speaker": "Doctor",
      "text": "We did an ultrasound on your abdominal wound yesterday. Good news — no abscess or fluid collection."
    },
    {
      "turn_number": 23,
      "time": "2118-07-20 10:01:00",
      "speaker": "Patient",
      "text": "It’s still tender. Should I keep cleaning it?"
    },
    {
      "turn_number": 24,
      "time": "2118-07-20 10:02:00",
      "speaker": "Doctor",
      "text": "Yes. The wound care team recommends cleaning it with a wound cleanser, applying DuoDerm gel, and covering it with a Mepilex dressing every three days."
    },
    {
      "turn_number": 25,
      "time": "2118-07-20 10:03:00",
      "speaker": "Patient",
      "text": "And the antibiotics? I was on ceftazidime before."
    },
    {
      "turn_number": 26,
      "time": "2118-07-20 10:04:00",
      "speaker": "Doctor",
      "text": "Since there’s no sign of active infection, we’re not continuing IV antibiotics. But you’ll keep the wound care at home."
    },
    {
      "turn_number": 27,
      "time": "2118-07-20 10:05:00",
      "speaker": "Patient",
      "text": "What about my breast wound? It’s still packed."
    },
    {
      "turn_number": 28,
      "time": "2118-07-20 10:06:00",
      "speaker": "Doctor",
      "text": "That wound is healing. We’ll keep packing it daily. You should follow up with the breast clinic as planned."
    },
    {
      "turn_number": 29,
      "time": "2118-07-20 15:50:00",
      "speaker": "Doctor",
      "text": "Quick update — we’ve replaced the temporary catheter in your neck with a tunneled one. It’s more secure and meant for longer use."
    },
    {
      "turn_number": 30,
      "time": "2118-07-20 15:51:00",
      "speaker": "Patient",
      "text": "Is that the same one?"
    },
    {
      "turn_number": 31,
      "time": "2118-07-20 15:52:00",
      "speaker": "Doctor",
      "text": "It’s a better version — same spot, but it goes under the skin and is less likely to get infected or move out of place."
    },
    {
      "turn_number": 32,
      "time": "2118-07-20 15:53:00",
      "speaker": "Patient",
      "text": "That sounds better."
    },
    {
      "turn_number": 33,
      "time": "2118-07-21 08:00:00",
      "speaker": "Doctor",
      "text": "Good news — you’re doing well. We’re planning to discharge you today."
    },
    {
      "turn_number": 34,
      "time": "2118-07-21 08:01:00",
      "speaker": "Patient",
      "text": "Already? What about dialysis?"
    },
    {
      "turn_number": 35,
      "time": "2118-07-21 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll go back to your regular dialysis schedule using the catheter in your neck. The transplant team will contact you to fix your arm graft as an outpatient."
    },
    {
      "turn_number": 36,
      "time": "2118-07-21 08:03:00",
      "speaker": "Patient",
      "text": "And my wounds?"
    },
    {
      "turn_number": 37,
      "time": "2118-07-21 08:04:00",
      "speaker": "Doctor",
      "text": "You’ll have a visiting nurse come to help with both wounds. They’ll follow the same cleaning and dressing routine we’ve been doing."
    },
    {
      "turn_number": 38,
      "time": "2118-07-21 08:05:00",
      "speaker": "Patient",
      "text": "I’m glad I won’t be alone with that."
    },
    {
      "turn_number": 39,
      "time": "2118-07-21 08:06:00",
      "speaker": "Doctor",
      "text": "We’ll also send your medications home with you. Most are the same, including your insulin, heart meds, and pain patches."
    },
    {
      "turn_number": 40,
      "time": "2118-07-21 08:07:00",
      "speaker": "Patient",
      "text": "No more IV antibiotics?"
    },
    {
      "turn_number": 41,
      "time": "2118-07-21 08:08:00",
      "speaker": "Doctor",
      "text": "No, we’re stopping those. The wounds aren’t infected now, so we don’t need them."
    },
    {
      "turn_number": 42,
      "time": "2118-07-21 08:09:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel much better knowing what’s next."
    },
    {
      "turn_number": 43,
      "time": "2118-07-21 08:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll make sure your daughter gets a call with the discharge details. You’ll be going home with support."
    },
    {
      "turn_number": 44,
      "time": "2118-07-21 08:11:00",
      "speaker": "Patient",
      "text": "She’ll be relieved. Thank you for explaining everything."
    },
    {
      "turn_number": 45,
      "time": "2118-07-21 08:12:00",
      "speaker": "Doctor",
      "text": "Of course. Take care, and we’ll see you in follow-up soon."
    }
  ],
  "summary": {
    "admission_start": "2118-07-18 17:20:00",
    "admission_end": "2118-07-21 16:32:00",
    "summary_paragraph": "The patient was re-admitted due to a thrombosed left upper extremity AV graft, preventing dialysis access. A fistulogram and thrombectomy were attempted but were unsuccessful due to persistent stenosis in the graft. A temporary dialysis catheter was placed in the left internal jugular vein and later converted to a tunneled catheter. The patient received one dialysis session during admission and was stabilized. Chronic abdominal and left breast wounds were assessed; no abscess was found, and wound care was optimized for home management. The transplant surgery team will contact the patient to schedule outpatient graft repair. She was discharged home with visiting nurse services for wound care and instructions to resume regular dialysis through the tunneled catheter.",
    "problems": [
      "Thrombosed left upper extremity AV graft",
      "End stage renal disease",
      "Abdominal wound",
      "Left breast wound",
      "Hypertension",
      "Coronary artery disease",
      "Diabetes mellitus type 2",
      "Chronic diastolic heart failure",
      "Morbid obesity",
      "Anemia"
    ]
  }
}
